// <sui-model> ===================================================================================================================
// SHATTERWORLD station UI, part 1 of 2: ONE view-model for every town screen (kitchen, apothecary, smithy, gem workshop, market, warehouse, notice board, town hall, garden, pack, gate, dialogue).
// suiModel() turns the game state into { title, sub, tabs, rows, info, acts, foot }; the SAME model is drawn into the flat DOM overlay (#sta) and into the big VR panel, and every action (A / X / Y) goes through
// suiDo(), so mouse, touch, keyboard, Xbox / PlayStation pad, phone pad and the VR laser can only ever differ in how they point at it.
// Actions are atomic (nothing is taken unless the whole job is affordable and fits) and every one of them reports through SUI.msg.
// ==============================================================================================================================
const SUI = { open: false, kind: '', tab: 0, row: 0, from: 'play', npc: null, dlgI: 0, aff: 0, imb: 0, seed: null, msg: '', msgOk: true, msgT: 0, hid: [], stale: null, M: null, dirty: true, icons: [], rep: { k: '', t: 0 }, acts: 0, first: 0, quest: 0 };
