const suiMsg = (t, ok = true) => { SUI.msg = t; SUI.msgOk = ok; SUI.msgT = 4; SUI.dirty = true; rsfx(ok ? 'pick1' : 'deny'); };
const suiTierName = t => ['Not built', 'Tier I', 'Tier II', 'Tier III'][t | 0] || 'Tier ' + t;
const suiCostLines = (cost) => { const c = costNorm(cost), out = []; if (c.gold) out.push({ t: 'cost', a: 'Gold', b: c.gold + ' (' + (RP.gold | 0) + ')', ok: RP.gold >= c.gold }); if (c.dust) out.push({ t: 'cost', a: 'Shards', b: c.dust + ' (' + (RP.dust | 0) + ')', ok: RP.dust >= c.dust }); for (const id in c.mats) out.push({ t: 'cost', a: MATS[id].name, b: c.mats[id] + ' (' + satCount(TOWN.sat, 'mat', id) + ')', ok: satCount(TOWN.sat, 'mat', id) >= c.mats[id], ic: ['mat', id] }); for (const id in c.ing) out.push({ t: 'cost', a: INGS[id].name, b: c.ing[id] + ' (' + satCount(TOWN.sat, 'ing', id) + ')', ok: satCount(TOWN.sat, 'ing', id) >= c.ing[id], ic: ['ing', id] }); return out; };
function suiBase() { return { title: SUI_NAME[SUI.kind] || '', sub: '', col: SUI_COL[SUI.kind] || '#ffe27a', tabs: [], tab: SUI.tab, rows: [], row: 0, info: [], acts: [], foot: [], empty: '', npc: null }; }
const suiAct = (id, label, o) => Object.assign({ id, label, primary: id === 'A', off: false, why: '' }, o || {});
const suiRarCol = it => RPG_RARITY_COL[RPG_RARITIES.indexOf(it.rarity)] || '#fff';
// ---- gear access ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
function suiGear() { const out = []; RPG_EQUIP.forEach((k, i) => { if (RP.equipped[k]) out.push({ it: RP.equipped[k], where: 'eq', slot: k, idx: i }); }); RP.bag.forEach((it, i) => { if (it) out.push({ it, where: 'bag', idx: i }); }); return out; }
