function suiItemRow(ref, i) { const it = ref.it; return { id: 'row:' + i, name: rpgItemName(it), sub: RPG_SLOT_LABEL[it.slot] + '  ·  ilvl ' + it.ilvl, right: ref.where === 'eq' ? 'WORN' : '', col: suiRarCol(it), ic: () => rpgIconBase(it), rar: RPG_RARITIES.indexOf(it.rarity), st: 'ok' }; }
