// ---- cook pot + alchemy table ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
const suiRecipeCtx = () => ({ tiers: townTiers(TOWN), seen: TOWN.seen, known: TOWN.known, level: RP.level });
function suiCookList() { const st = SUI.kind, ctx = suiRecipeCtx(), tier = townTier(TOWN, SUI_ROLE[st]), out = []; for (const id of FOOD_RECIPE_IDS) { const r = FOOD_RECIPES[id]; if (r.station !== st) continue; const known = foodRecipeKnown(r, ctx); out.push({ r, known, lock: !known || r.tier > Math.max(1, tier) }); } return out; }
